from pathlib import Path
import base64, zlib, subprocess, tempfile
data=zlib.decompress(base64.b64decode(""""""))
root=Path("/tmp/src/S3XYButtonBridgeAndroid")
with tempfile.NamedTemporaryFile(prefix="v076_",suffix=".patch",delete=False) as f:
    f.write(data)
    patch_path=f.name
subprocess.run(["patch","-p1","-d",str(root),"-i",patch_path],check=True)
print("v0.7.6 fast highbeam patch applied")
